CREATE TABLE IF NOT EXISTS publishers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,slug VARCHAR(140) NOT NULL UNIQUE,email VARCHAR(180) NOT NULL UNIQUE,status ENUM('active','suspended') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,publisher_id BIGINT UNSIGNED NULL,name VARCHAR(120) NOT NULL,email VARCHAR(180) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('superadmin','publisher_admin','editor','member') NOT NULL DEFAULT 'member',birth_date DATE NULL,status ENUM('active','blocked') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_users_publisher FOREIGN KEY(publisher_id) REFERENCES publishers(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS plans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code ENUM('basic','premium','ultimate') NOT NULL UNIQUE,name VARCHAR(60) NOT NULL,monthly_price DECIMAL(10,2) NOT NULL,annual_price DECIMAL(10,2) NULL,description VARCHAR(255) NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
INSERT IGNORE INTO plans(code,name,monthly_price,annual_price,description) VALUES('basic','Básico',9.90,95.04,'Catálogo básico'),('premium','Premium',19.90,191.04,'Catálogo completo'),('ultimate','Ultimate',29.90,287.04,'Vídeos exclusivos');
CREATE TABLE IF NOT EXISTS subscriptions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,plan_id BIGINT UNSIGNED NOT NULL,asaas_customer_id VARCHAR(80) NULL,asaas_subscription_id VARCHAR(80) NULL,status ENUM('trial','active','overdue','cancelled','expired') NOT NULL DEFAULT 'trial',started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,trial_ends_at DATETIME NULL,ends_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(plan_id) REFERENCES plans(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS mangas (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,publisher_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,slug VARCHAR(200) NOT NULL UNIQUE,synopsis TEXT NULL,cover_url VARCHAR(500) NULL,rating ENUM('L','10','12','14','16','18') NOT NULL DEFAULT 'L',status ENUM('draft','published','archived') NOT NULL DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(publisher_id) REFERENCES publishers(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS chapters (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,manga_id BIGINT UNSIGNED NOT NULL,number INT NOT NULL,title VARCHAR(180) NOT NULL,content_url VARCHAR(500) NOT NULL,minimum_plan ENUM('basic','premium','ultimate') NOT NULL DEFAULT 'basic',published_at DATETIME NULL,UNIQUE KEY uq_chapter(manga_id,number),FOREIGN KEY(manga_id) REFERENCES mangas(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS exclusive_videos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,publisher_id BIGINT UNSIGNED NOT NULL,uploaded_by BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,description TEXT NULL,video_url VARCHAR(500) NOT NULL,thumbnail_url VARCHAR(500) NULL,duration_seconds INT UNSIGNED NULL,status ENUM('processing','published','hidden') NOT NULL DEFAULT 'processing',minimum_plan ENUM('ultimate') NOT NULL DEFAULT 'ultimate',published_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(publisher_id) REFERENCES publishers(id) ON DELETE CASCADE,FOREIGN KEY(uploaded_by) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS support_tickets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,subject VARCHAR(180) NOT NULL,message TEXT NOT NULL,status ENUM('open','in_progress','closed') NOT NULL DEFAULT 'open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS support_replies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ticket_id BIGINT UNSIGNED NOT NULL,author_id BIGINT UNSIGNED NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(ticket_id) REFERENCES support_tickets(id) ON DELETE CASCADE,FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS community_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,message VARCHAR(1000) NOT NULL,status ENUM('visible','hidden') NOT NULL DEFAULT 'visible',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_community_time(created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,message TEXT NOT NULL,read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(180) NOT NULL,metadata JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS private_documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,publisher_id BIGINT UNSIGNED NOT NULL,uploaded_by BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,description TEXT NULL,file_path VARCHAR(500) NOT NULL,minimum_plan ENUM('basic','premium','ultimate') NOT NULL DEFAULT 'premium',status ENUM('published','hidden') NOT NULL DEFAULT 'published',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(publisher_id) REFERENCES publishers(id) ON DELETE CASCADE,FOREIGN KEY(uploaded_by) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS webauthn_credentials (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,credential_id VARBINARY(255) NOT NULL UNIQUE,public_key_x VARBINARY(32) NOT NULL,public_key_y VARBINARY(32) NOT NULL,sign_count INT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,last_used_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
